-- =============================================================================
-- LIMS IDIC · Entrega R2/R4 · frente r2a · Aiuken
-- Formularios especializados (T10), preparación y acondicionamiento de muestras
-- (T29) y preparación del trabajo del DSA (T26); arrastre de R1: Certificado de
-- Resistencia Balística (CRB) e Informe de Ensayo de Rechazo del LRB (BL-026).
-- =============================================================================
-- Contrato: docs/FLUJO_FORMULARIOS_ESPECIALIZADOS.md. Reglas puras en
-- apps/api/src/formularios/*.ts (aql, lrb, hcp, preparacion, trabajo, variantes).
--
--   1. registro_especializado (+ evento y adjunto): el dato primario de cada
--      formulario (disparos del LRB, HCP por vehículo, inspección AQL,
--      microbiología, panel sensorial), la preparación de cada muestra y la
--      documentación del trabajo del DSA, con su bitácora (quién, cuándo,
--      qué cambió y por qué).
--   2. Tipos de documento CERTIFICADO_RESISTENCIA_BALISTICA e INFORME_RECHAZO en
--      la matriz de firmas, su circuito por defecto y sus plantillas.
--   3. Permiso ot.preparacion.aprobar (Jefe de Laboratorio; la cascada de
--      align_cierre_permisos.sql lo da a Sección y Departamento).
--   4. Parámetros de la operación (valores por defecto de los documentos del
--      IDIC, «por confirmar» donde corresponde): activación de variantes por
--      método y por laboratorio, tabla de amenazas del LRB, nivel y AQL por
--      clase, plantilla de HCP del VLCB, campos de preparación por laboratorio,
--      aprobación de la documentación del trabajo, microbiología y sensorial.
--
-- Aditivo e idempotente: CREATE … IF NOT EXISTS, ON CONFLICT DO NOTHING (un
-- parámetro que el IDIC ya cambió no se repone). Va ANTES de
-- align_cierre_permisos.sql en ORDEN_SQL.txt.
-- =============================================================================

-- --- 1. Registro de los formularios especializados -----------------------------
CREATE TABLE IF NOT EXISTS registro_especializado (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id       UUID NOT NULL REFERENCES tenant(id),
  ot_id           UUID NOT NULL REFERENCES orden_trabajo(id) ON DELETE CASCADE,
  -- Muestra (vehículo del SVM, muestra preparada) y ensayo (micro, sensorial), si aplica.
  muestra_id      UUID REFERENCES muestra(id) ON DELETE CASCADE,
  resultado_id    UUID REFERENCES resultado(id) ON DELETE CASCADE,
  -- Laboratorio dueño del registro (preparación, documentación del trabajo).
  unidad_id       UUID REFERENCES unidad(id),
  variante        VARCHAR(30) NOT NULL CHECK (variante IN (
                    'lrb_disparos','svm_hcp','svm_lote','aql','lmb_micro','les_panel','preparacion','trabajo')),
  -- Distingue registros de la misma variante en la OT (Nº de vehículo, laboratorio…).
  clave           VARCHAR(80) NOT NULL DEFAULT '',
  datos           JSONB NOT NULL DEFAULT '{}'::jsonb,
  estado          VARCHAR(20) NOT NULL DEFAULT 'borrador',
  veredicto       VARCHAR(20),
  resumen         TEXT,
  version         INT NOT NULL DEFAULT 1,
  creado_por      UUID REFERENCES usuario(id),
  actualizado_por UUID REFERENCES usuario(id),
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT uq_registro_especializado UNIQUE (ot_id, variante, clave)
);
CREATE INDEX IF NOT EXISTS idx_reg_esp_tenant_variante ON registro_especializado (tenant_id, variante, estado);
CREATE INDEX IF NOT EXISTS idx_reg_esp_muestra ON registro_especializado (muestra_id) WHERE muestra_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_reg_esp_resultado ON registro_especializado (resultado_id) WHERE resultado_id IS NOT NULL;
COMMENT ON TABLE registro_especializado IS
  'Dato primario de los formularios especializados (T10), preparación de muestras (T29) y documentación del trabajo DSA (T26). docs/FLUJO_FORMULARIOS_ESPECIALIZADOS.md';

-- Bitácora: cada guardado, corrección (con motivo), envío, aprobación o devolución.
CREATE TABLE IF NOT EXISTS registro_especializado_evento (
  id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id      UUID NOT NULL REFERENCES tenant(id),
  registro_id    UUID NOT NULL REFERENCES registro_especializado(id) ON DELETE CASCADE,
  accion         VARCHAR(30) NOT NULL,
  version        INT NOT NULL,
  estado_antes   VARCHAR(20),
  estado_despues VARCHAR(20),
  -- Lo que había antes de una corrección (no se borra nada).
  datos_antes    JSONB,
  motivo         TEXT,
  usuario_id     UUID REFERENCES usuario(id),
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_reg_esp_evento ON registro_especializado_evento (registro_id, created_at);

-- Adjuntos (proyectos de párrafo, oficios, planillas): PDF o imagen, con su hash.
CREATE TABLE IF NOT EXISTS registro_especializado_adjunto (
  id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id    UUID NOT NULL REFERENCES tenant(id),
  registro_id  UUID NOT NULL REFERENCES registro_especializado(id) ON DELETE CASCADE,
  nombre       VARCHAR(200) NOT NULL,
  mime         VARCHAR(80) NOT NULL,
  bytes        INT NOT NULL,
  datos        TEXT NOT NULL,
  hash_sha256  VARCHAR(64) NOT NULL,
  subido_por   UUID REFERENCES usuario(id),
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  deleted_at   TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_reg_esp_adjunto ON registro_especializado_adjunto (registro_id) WHERE deleted_at IS NULL;

-- --- 2. CRB e Informe de Ensayo de Rechazo del LRB (BL-026, EP-05 §6) ------------
-- La matriz de firmas admite los dos tipos nuevos (la restricción se recrea con la lista completa).
ALTER TABLE flujo_firma DROP CONSTRAINT IF EXISTS flujo_firma_tipo_documento_check;
ALTER TABLE flujo_firma ADD CONSTRAINT flujo_firma_tipo_documento_check CHECK (tipo_documento IN (
  'INFORME_ENSAYO','IVC','INFORME_TECNICO','CERTIFICADO_CALIBRACION',
  'INFORME_INSPECCION','CERTIFICADO_CONFORMIDAD','INFORME_INCUMPLIMIENTO',
  'COTIZACION','OT_DISPOSICION','SOLICITUD_ADQUISICION','OFICIO',
  'CERTIFICADO_RESISTENCIA_BALISTICA','INFORME_RECHAZO'));

-- Circuito por defecto (POR CONFIRMAR, EP-05 P2): firma el Jefe LRB y oficializa el
-- Jefe DSA «por orden del Director». Se configura por unidad en «Matriz de firmas».
INSERT INTO flujo_firma (id, tenant_id, tipo_documento, unidad_id, orden, accion, rol_id,
                         nivel_unidad, unidad_destino_id, obligatorio, activo, descripcion)
SELECT gen_random_uuid(), t.id, f.tipo, NULL, f.orden, f.accion, r.id, f.nivel, NULL, TRUE, TRUE, f.descripcion
  FROM (VALUES
    ('CERTIFICADO_RESISTENCIA_BALISTICA', 1, 'FIRMA',      'JEFE_LAB',   'MISMA',        'Firma el Jefe del LRB'),
    ('CERTIFICADO_RESISTENCIA_BALISTICA', 2, 'OFICIALIZA', 'JEFE_DEPTO', 'DEPARTAMENTO', 'Firma el Jefe DSA «por orden del Director»'),
    ('INFORME_RECHAZO',                   1, 'ELABORA',    'JEFE_LAB',   'MISMA',        'Elabora el Jefe del LRB'),
    ('INFORME_RECHAZO',                   2, 'FIRMA',      'JEFE_DEPTO', 'DEPARTAMENTO', 'Firma el Jefe DSA «por orden del Director»')
  ) AS f(tipo, orden, accion, rol, nivel, descripcion)
  JOIN tenant t ON t.codigo = 'IDIC'
  JOIN rol r    ON r.tenant_id = t.id AND r.codigo = f.rol
 WHERE NOT EXISTS (
   SELECT 1 FROM flujo_firma x
    WHERE x.tenant_id = t.id AND x.tipo_documento = f.tipo AND x.orden = f.orden AND x.unidad_id IS NULL);

