-- --- 3. Permisos ---------------------------------------------------------------
INSERT INTO permiso (id, codigo, modulo, accion, descripcion) VALUES
  (gen_random_uuid(), 'ot.preparacion.aprobar', 'ot', 'preparacion_aprobar',
   'Aprobar, validar o devolver la documentación del trabajo antes de la ejecución (EP-05 2.3)')
ON CONFLICT (codigo) DO NOTHING;
INSERT INTO rol_permiso (rol_id, permiso_id)
SELECT r.id, p.id FROM rol r JOIN permiso p ON p.codigo = 'ot.preparacion.aprobar'
 WHERE COALESCE(r.alias_de, r.codigo) IN ('SUPERADMIN', 'JEFE_LAB', 'JEFE_SECCION', 'JEFE_DEPTO')
ON CONFLICT DO NOTHING;

-- --- 4. Parámetros de la operación -------------------------------------------------
-- 4a. Activación de las variantes por método del catálogo (código del método).
--     Microbiología y sensorial quedan INACTIVAS: el IDIC aún no decide si quiere
--     las etapas o solo el resultado consolidado (EP-02 P1); se activan aquí.
INSERT INTO parametro_sistema (tenant_id, categoria, codigo, etiqueta, orden, valor, activo)
SELECT m.tenant_id, 'captura_variante_metodo', m.codigo, left(m.codigo || ' · ' || m.nombre, 160), v.orden, v.variante, v.activo
  FROM (VALUES
    -- LRB · registro de disparos (EP-05 4.1)
    ('3376', 'lrb_disparos', 1, TRUE), ('3388', 'lrb_disparos', 2, TRUE), ('3366', 'lrb_disparos', 3, TRUE),
    ('11173', 'lrb_disparos', 4, TRUE), ('3352', 'lrb_disparos', 5, TRUE), ('3362', 'lrb_disparos', 6, TRUE),
    ('10746', 'lrb_disparos', 7, TRUE), ('10750', 'lrb_disparos', 8, TRUE),
    -- SVM · HCP por vehículo (EP-05 4.6): métodos ligados a los grupos de la HCP del VLCB
    ('539', 'svm_hcp', 20, TRUE), ('540', 'svm_hcp', 21, TRUE), ('542', 'svm_hcp', 22, TRUE), ('543', 'svm_hcp', 23, TRUE),
    ('545', 'svm_hcp', 24, TRUE), ('548', 'svm_hcp', 25, TRUE), ('549', 'svm_hcp', 26, TRUE), ('550', 'svm_hcp', 27, TRUE),
    ('555', 'svm_hcp', 28, TRUE), ('1410', 'svm_hcp', 29, TRUE), ('1413', 'svm_hcp', 30, TRUE), ('1422', 'svm_hcp', 31, TRUE),
    ('1423', 'svm_hcp', 32, TRUE), ('1425', 'svm_hcp', 33, TRUE), ('1426', 'svm_hcp', 34, TRUE), ('1429', 'svm_hcp', 35, TRUE),
    -- LCC y LTX · inspección por atributos del lote (EP-03 3.7)
    ('3704', 'aql', 40, TRUE), ('3705', 'aql', 41, TRUE),
    -- LMB · siembra, incubación y lectura (EP-02 3.3–3.5) · INACTIVO hasta EP-02 P1
    ('428', 'lmb_micro', 60, FALSE), ('1139', 'lmb_micro', 61, FALSE), ('432', 'lmb_micro', 62, FALSE), ('3420', 'lmb_micro', 63, FALSE),
    ('417', 'lmb_micro', 64, FALSE), ('421', 'lmb_micro', 65, FALSE), ('424', 'lmb_micro', 66, FALSE), ('425', 'lmb_micro', 67, FALSE),
    ('426', 'lmb_micro', 68, FALSE), ('416', 'lmb_micro', 69, FALSE), ('422', 'lmb_micro', 70, FALSE), ('429', 'lmb_micro', 71, FALSE),
    -- LES · panel sensorial (EP-02 3.6–3.8) · INACTIVO hasta EP-02 P1
    ('461', 'les_panel', 80, FALSE), ('1116', 'les_panel', 81, FALSE), ('463', 'les_panel', 82, FALSE), ('462', 'les_panel', 83, FALSE),
    ('464', 'les_panel', 84, FALSE), ('1117', 'les_panel', 85, FALSE)
