  JOIN cat_metodo m ON m.codigo = v.codigo AND m.deleted_at IS NULL
ON CONFLICT (tenant_id, categoria, codigo) DO NOTHING;
-- (captura_variante_laboratorio: sin filas; un laboratorio se da de alta desde la pantalla.)

-- 4b. Reglas simples (opción, entero, sí/no, varias).
INSERT INTO parametro_sistema (tenant_id, categoria, codigo, etiqueta, orden, valor)
SELECT t.id, v.categoria, v.codigo, v.etiqueta, v.orden, v.valor
  FROM tenant t
 CROSS JOIN (VALUES
  -- LRB (EP-05 §5.2, P4): velocidad que se compara con la ventana · plazo de apelación (IE Rechazo J.82352).
  ('lrb', 'velocidad_manda', 'Velocidad que se compara con la ventana (v1 | v2 | promedio)', 1, 'v1'),
  ('lrb', 'plazo_apelacion', 'Plazo de apelación del rechazo (días hábiles)', 2, '5'),
  -- Inspección por atributos NCh 44 (EP-03 P5, EP-05 P15): nivel y AQL por clase.
  ('inspeccion_aql', 'nivel', 'Nivel de inspección', 1, 'II'),
  ('inspeccion_aql', 'aql_inspeccion', 'AQL por defecto de una inspección del IVC', 2, '2,5'),
  ('inspeccion_aql', 'aql_clase_a', 'AQL clase A (crítico)', 3, '0'),
  ('inspeccion_aql', 'aql_clase_b', 'AQL clase B (mayor)', 4, '2,5'),
  ('inspeccion_aql', 'aql_clase_c', 'AQL clase C (menor)', 5, '6,5'),
  -- Documentación del trabajo DSA (EP-05 2.3).
  ('preparacion_trabajo', 'exige_aprobacion', 'Laboratorios cuya documentación se aprueba antes de ejecutar', 1, 'LRB,SVM'),
  ('preparacion_trabajo', 'bloquea_captura', 'La captura espera la aprobación', 2, 'si'),
  -- Microbiología (EP-02 3.4, P3): lecturas programadas.
  ('micro', 'lecturas_h', 'Lecturas programadas (horas desde la siembra)', 1, '24,48,72'),
  -- Sensorial (EP-02 3.8, P4): nivel de significancia y jueces mínimos.
  ('sensorial', 'alfa', 'Nivel de significancia α', 1, '0,05'),
  ('sensorial', 'jueces_min', 'Jueces válidos mínimos', 2, '6')
 ) AS v(categoria, codigo, etiqueta, orden, valor)
ON CONFLICT (tenant_id, categoria, codigo) DO NOTHING;

-- 4c. Tablas (JSON): amenazas del LRB, rangos sensoriales, criterios RSA (vacía:
--     sin plan se usa el Máx del ensayo, como el LIMS antiguo «según RSA vigente»).
INSERT INTO parametro_sistema (tenant_id, categoria, codigo, etiqueta, orden, valor)
SELECT t.id, v.categoria, v.codigo, v.etiqueta, v.orden, v.valor
  FROM tenant t
 CROSS JOIN (VALUES
  ('lrb', 'amenazas', 'Tabla de amenazas por norma y nivel', 3, $am$[{"clave":"NIJ0101-IIIA-9MM","norma":"NIJ 0101.04","nivel":"IIIA","elemento":"chaleco","municion":"9×19 mm FMJ RN","masa_g":8.03,"v_min":427,"v_max":445,"disparos":6,"trauma_max":44,"disparos_trauma":3,"testigo":false,"criterio":"Sin penetración completa y trauma ≤ 44 mm"},{"clave":"NIJ0101-IIIA-44MAG","norma":"NIJ 0101.04","nivel":"IIIA","elemento":"chaleco","municion":".44 Magnum SJHP","masa_g":15.6,"v_min":427,"v_max":445,"disparos":6,"trauma_max":44,"disparos_trauma":3,"testigo":false,"criterio":"Sin penetración completa y trauma ≤ 44 mm"},{"clave":"NIJ0106-IIA-9MM","norma":"NIJ 0106.01","nivel":"II-A","elemento":"casco","municion":"9 mm FMJ","masa_g":8,"v_min":317,"v_max":347,"disparos":4,"trauma_max":null,"disparos_trauma":0,"testigo":true,"criterio":"Sin penetración del casco ni de la placa testigo"},{"clave":"NIJ0106-IIA-357","norma":"NIJ 0106.01","nivel":"II-A","elemento":"casco","municion":".357 Magnum JSP","masa_g":10.2,"v_min":366,"v_max":396,"disparos":4,"trauma_max":null,"disparos_trauma":0,"testigo":true,"criterio":"Sin penetración del casco ni de la placa testigo"},{"clave":"NIJ0108-IIIA","norma":"NIJ 0108.01","nivel":"IIIA","elemento":"probeta","municion":".44 Magnum","masa_g":15.55,"v_min":411,"v_max":441,"disparos":5,"trauma_max":null,"disparos_trauma":0,"testigo":false,"criterio":"Sin penetración"},{"clave":"NIJ0108-III","norma":"NIJ 0108.01","nivel":"III","elemento":"probeta","municion":"7,62×51 mm FMJ","masa_g":9.7,"v_min":823,"v_max":853,"disparos":5,"trauma_max":null,"disparos_trauma":0,"testigo":false,"criterio":"Sin penetración"},{"clave":"UL752-2","norma":"UL 752","nivel":"2","elemento":"probeta","municion":".357 Magnum","masa_g":10.2,"v_min":381,"v_max":419,"disparos":3,"trauma_max":null,"disparos_trauma":0,"testigo":true,"criterio":"Sin penetración ni daño en el testigo"},{"clave":"UL752-3","norma":"UL 752","nivel":"3","elemento":"probeta","municion":".44 Magnum","masa_g":15.6,"v_min":411,"v_max":452,"disparos":3,"trauma_max":null,"disparos_trauma":0,"testigo":true,"criterio":"Sin penetración ni daño en el testigo"},{"clave":"UL752-5","norma":"UL 752","nivel":"5","elemento":"probeta","municion":"7,62 mm FMJ","masa_g":9.7,"v_min":838,"v_max":922,"disparos":3,"trauma_max":null,"disparos_trauma":0,"testigo":true,"criterio":"Sin penetración ni daño en el testigo"}]$am$),
  ('sensorial', 'rangos', 'Rangos por atributo (Listado LES)', 3,
   '[{"prueba":"Aceptabilidad","atributo":"Aceptabilidad","min":5,"max":9},{"prueba":"Categoría","atributo":"Apariencia","min":6,"max":9},{"prueba":"Categoría","atributo":"Color","min":4.5,"max":5.5},{"prueba":"Categoría","atributo":"Olor","min":4.5,"max":5.5},{"prueba":"Categoría","atributo":"Sabor","min":4.5,"max":5.5},{"prueba":"Categoría","atributo":"Consistencia","min":4.5,"max":5.5},{"prueba":"Categoría","atributo":"Textura","min":4.5,"max":5.5},{"prueba":"Categoría","atributo":"Sabor residual","min":0,"max":2}]'),
  ('rsa_criterios', 'tabla', 'Planes n, c, m, M por ensayo y producto (RSA)', 1, '[]')
 ) AS v(categoria, codigo, etiqueta, orden, valor)
ON CONFLICT (tenant_id, categoria, codigo) DO NOTHING;

-- 4d. Plantilla de la HCP del VLCB (LVM-PG01-IT03-FORM02 Rev03, 379 ítems con clase).
