-- 4f. Preparación obligatoria antes de capturar, por laboratorio (activo = obligatoria).
--     Por defecto ninguna (la captura estándar no cambia); se activa desde la pantalla.
INSERT INTO parametro_sistema (tenant_id, categoria, codigo, etiqueta, orden, activo)
SELECT t.id, 'preparacion_obligatoria', v.codigo, v.etiqueta, v.orden, v.activo
  FROM tenant t
 CROSS JOIN (VALUES
  ('LQC', 'LQC · preparación obligatoria antes de capturar', 1, FALSE),
  ('LPN', 'LPN · preparación obligatoria antes de capturar', 2, FALSE),
  ('LME', 'LME · preparación obligatoria antes de capturar', 3, FALSE),
  ('LQA', 'LQA · preparación obligatoria antes de capturar', 4, FALSE),
  ('LMB', 'LMB · preparación obligatoria antes de capturar', 5, FALSE),
  ('LES', 'LES · preparación obligatoria antes de capturar', 6, FALSE),
  ('LCC', 'LCC · preparación obligatoria antes de capturar', 7, FALSE),
  ('LTX', 'LTX · preparación obligatoria antes de capturar', 8, FALSE),
  ('LRB', 'LRB · preparación obligatoria antes de capturar', 9, FALSE),
  ('LEM', 'LEM · preparación obligatoria antes de capturar', 10, FALSE),
  ('LAM', 'LAM · preparación obligatoria antes de capturar', 11, FALSE),
  ('SEO', 'SEO · preparación obligatoria antes de capturar', 12, FALSE),
  ('SVM', 'SVM · preparación obligatoria antes de capturar', 13, FALSE)
 ) AS v(codigo, etiqueta, orden, activo)
ON CONFLICT (tenant_id, categoria, codigo) DO NOTHING;
